/**
 * Modules d'expertise de la banque de quiz — extension.
 *
 * Huit modules transverses (six niveaux chacun) et deux examens de
 * synthèse. Même contrat que server/quiz/quiz-bank-modules.js :
 *
 *   - `correct` désigne la lettre de la bonne réponse ;
 *   - `category` alimente le reporting « questions les plus ratées » ;
 *   - `explanation` s'affiche après la réponse et doit apprendre quelque
 *     chose même à celui qui a trouvé — on y met le raisonnement ou le
 *     contre-exemple, pas la reformulation de la bonne option.
 *
 * Indexation : modules[<clé>][<niveau>] → tableau de questions.
 *
 * La position de la bonne réponse est volontairement variée d'une
 * question à l'autre : une banque où la bonne réponse est trop souvent
 * en B se réussit à l'habitude plutôt qu'à la compréhension.
 */

